import { test, expect } from '@playwright/test';

test.describe('Google OAuth Login', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-app-url.com');
  });

  test('should display the login button', async ({ page }) => {
    const loginButton = page.getByRole('button', { name: /log in with google/i });
    await expect(loginButton).toBeVisible();
  });

  test('should log in successfully using Google OAuth', async ({ page }) => {
    const loginButton = page.getByRole('button', { name: /log in with google/i });
    await loginButton.click();

    // Assuming the Google login page is opened
    await page.fill('input[type="email"]', 'your-email@gmail.com');
    await page.click('button[type="submit"]');

    await page.fill('input[type="password"]', 'your-password');
    await page.click('button[type="submit"]');

    // Redirect back to the app
    await expect(page).toHaveURL('https://your-app-url.com/dashboard');
    const welcomeMessage = page.getByText(/welcome back/i);
    await expect(welcomeMessage).toBeVisible();
  });
});
